-- Hosbah queries (MH-575 F6: DB metrics history).

-- name: LastDataServiceMetric :one
-- System scope (the sampler): the most recent minute row for a service, to compute this sample's
-- rate_per_sec from the delta of tx_counter. No row yet -> sql.ErrNoRows, treated as "first sample".
SELECT * FROM data_service_metrics WHERE service_id = sqlc.arg('service_id') AND step = 60 ORDER BY at DESC LIMIT 1;

-- name: RecordDataServiceMetric :exec
-- System scope (the sampler): one minute's reading. Idempotent by (service_id, step, at) — a sampler
-- tick that overlaps a previous one (should not happen with a single scheduler, but is cheap to make
-- safe) just overwrites with the newer reading rather than double-counting.
INSERT INTO data_service_metrics (service_id, team_id, at, step, connections, max_connections, cache_hit_ratio, size_bytes, slow_query_count, tx_counter, rate_per_sec)
VALUES (sqlc.arg('service_id'), sqlc.arg('team_id'), sqlc.arg('at'), 60, sqlc.arg('connections'), sqlc.arg('max_connections'),
    sqlc.arg('cache_hit_ratio'), sqlc.arg('size_bytes'), sqlc.arg('slow_query_count'), sqlc.arg('tx_counter'), sqlc.arg('rate_per_sec'))
ON CONFLICT (service_id, step, at) DO UPDATE SET
    connections = EXCLUDED.connections, max_connections = EXCLUDED.max_connections, cache_hit_ratio = EXCLUDED.cache_hit_ratio,
    size_bytes = EXCLUDED.size_bytes, slow_query_count = EXCLUDED.slow_query_count, tx_counter = EXCLUDED.tx_counter,
    rate_per_sec = EXCLUDED.rate_per_sec, updated_at = now();

-- name: DataServiceMetricsSince :many
-- Team scope: one service's samples (minute and 15-minute rows) since a time, oldest first.
SELECT at, step, connections, max_connections, cache_hit_ratio, size_bytes, slow_query_count, tx_counter, rate_per_sec
FROM data_service_metrics
WHERE service_id = sqlc.arg('service_id') AND team_id = sqlc.arg('team_id') AND at >= sqlc.arg('since')
ORDER BY at;

-- name: ServicesForMetricsSampling :many
-- System scope (the sampler): every running Postgres/MySQL service across every team, full row since
-- Insights() needs a complete db.DataService (workload/origin fields for sealRoot and execTarget).
-- Redis/MinIO/imported-without-credentials are filtered by the caller the same way db.insights already
-- gates them (preflightQuery), since that logic is not SQL.
SELECT * FROM data_services WHERE status = 'running' AND kind IN ('postgres', 'mysql');

-- name: CompactDataServiceMetrics :execrows
-- System scope (the retention job): minute rows older than @before become 15-minute rows. A
-- 15-minute bucket that straddles @before is merged across runs, so a bucket ends up the same as if
-- it had been compacted at once. Gauges are averaged; rate_per_sec is averaged; tx_counter keeps the
-- latest (by "at") reading in the bucket, so a later compaction can still take a correct delta from it.
WITH moved AS (
    DELETE FROM data_service_metrics dsm WHERE dsm.step = 60 AND dsm.at < sqlc.arg('before')::timestamptz
    RETURNING dsm.service_id, dsm.team_id, dsm.at, dsm.connections, dsm.max_connections, dsm.cache_hit_ratio,
        dsm.size_bytes, dsm.slow_query_count, dsm.tx_counter, dsm.rate_per_sec
), b AS (
    SELECT mv.service_id, mv.team_id, to_timestamp(floor(extract(epoch FROM mv.at) / 900) * 900) AS bucket,
        mv.at, mv.connections, mv.max_connections, mv.cache_hit_ratio, mv.size_bytes, mv.slow_query_count, mv.tx_counter, mv.rate_per_sec
    FROM moved mv
), agg AS (
    SELECT b.service_id, b.team_id, b.bucket,
        avg(b.connections)::bigint AS connections, max(b.max_connections)::bigint AS max_connections,
        avg(b.cache_hit_ratio)::float8 AS cache_hit_ratio, avg(b.size_bytes)::bigint AS size_bytes,
        avg(b.slow_query_count)::bigint AS slow_query_count, avg(b.rate_per_sec)::float8 AS rate_per_sec,
        (array_agg(b.tx_counter ORDER BY b.at DESC))[1]::bigint AS tx_counter
    FROM b GROUP BY b.service_id, b.team_id, b.bucket
)
INSERT INTO data_service_metrics (service_id, team_id, at, step, connections, max_connections, cache_hit_ratio, size_bytes, slow_query_count, tx_counter, rate_per_sec)
SELECT agg.service_id, agg.team_id, agg.bucket, 900, agg.connections, agg.max_connections, agg.cache_hit_ratio,
    agg.size_bytes, agg.slow_query_count, agg.tx_counter, agg.rate_per_sec
FROM agg
ON CONFLICT (service_id, step, at) DO UPDATE SET
    connections = (data_service_metrics.connections + EXCLUDED.connections) / 2,
    max_connections = greatest(data_service_metrics.max_connections, EXCLUDED.max_connections),
    cache_hit_ratio = (data_service_metrics.cache_hit_ratio + EXCLUDED.cache_hit_ratio) / 2,
    size_bytes = (data_service_metrics.size_bytes + EXCLUDED.size_bytes) / 2,
    slow_query_count = (data_service_metrics.slow_query_count + EXCLUDED.slow_query_count) / 2,
    rate_per_sec = (data_service_metrics.rate_per_sec + EXCLUDED.rate_per_sec) / 2,
    tx_counter = EXCLUDED.tx_counter, updated_at = now();

-- name: PruneDataServiceMetrics :execrows
-- System scope (the retention job): 15-minute rows older than @before are dropped.
DELETE FROM data_service_metrics WHERE step = 900 AND at < sqlc.arg('before')::timestamptz;
